<?php
declare(strict_types=1);
require_once __DIR__ . '/adminauth.php';
require_admin();
$db = database();
$stats = $db->query("SELECT (SELECT COUNT(*) FROM tbl_product WHERE is_active=1) AS products, (SELECT COALESCE(SUM(stock),0) FROM tbl_product WHERE is_active=1) AS units, (SELECT COUNT(*) FROM tbl_product WHERE is_active=1 AND stock <= 10) AS low_stock, (SELECT COALESCE(SUM(payment_amount),0) FROM tbl_payment WHERE payment_status='paid') AS sales, (SELECT COUNT(*) FROM tbl_delivery WHERE status IN ('pending','assigned','shipping')) AS deliveries")->fetch();
$lowStock = $db->query('SELECT productID, product_name, size, stock, image_path FROM tbl_product WHERE is_active=1 AND stock <= 10 ORDER BY stock ASC, product_name ASC LIMIT 6')->fetchAll();
$recent = $db->query('SELECT st.transaction_type, st.quantity, st.transaction_date, p.product_name, p.size FROM tbl_stock_transaction st INNER JOIN tbl_product p ON p.productID=st.productID ORDER BY st.transactionID DESC LIMIT 5')->fetchAll();
$activePage = 'dashboard';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dashboard | H2O2U Admin</title><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="admin-dashboard.css"></head><body class="admin-app"><?php include __DIR__ . '/admin_sidebar.php'; ?><main class="container"><header class="dashboard-top"><div><p class="eyebrow">H2O2U control centre</p><h1>Welcome back, <?= htmlspecialchars($_SESSION['admin_name'] ?? 'Admin') ?></h1><p>Here is a clear view of your water-delivery operations.</p></div><div class="admin-user"><i class="fa-solid fa-user-shield"></i><span><?= htmlspecialchars($_SESSION['admin_name'] ?? 'Admin') ?></span></div></header><section class="metric-grid"><article class="metric"><span class="metric-label">Active products</span><div class="metric-value"><?= (int)$stats['products'] ?></div><span class="metric-note">Visible to customers</span><span class="metric-icon"><i class="fa-solid fa-bottle-water"></i></span></article><article class="metric success"><span class="metric-label">Available units</span><div class="metric-value"><?= number_format((int)$stats['units']) ?></div><span class="metric-note">Across all active products</span><span class="metric-icon"><i class="fa-solid fa-boxes-stacked"></i></span></article><article class="metric warning"><span class="metric-label">Low-stock products</span><div class="metric-value"><?= (int)$stats['low_stock'] ?></div><span class="metric-note">10 units or fewer</span><span class="metric-icon"><i class="fa-solid fa-triangle-exclamation"></i></span></article><article class="metric"><span class="metric-label">Paid sales</span><div class="metric-value"><?= number_format((float)$stats['sales'],0) ?> Ks</div><span class="metric-note"><?= (int)$stats['deliveries'] ?> delivery tasks active</span><span class="metric-icon"><i class="fa-solid fa-chart-line"></i></span></article></section><div class="row g-4"><section class="col-xl-7"><div class="admin-panel card-body h-100"><div class="section-head"><div><h2>Low-stock alert</h2><p>Restock these products before they run out.</p></div><a class="btn btn-sm btn-outline-primary" href="admin_stock.php">Manage stock</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>Size</th><th>Available</th><th></th></tr></thead><tbody><?php if (!$lowStock): ?><tr><td colspan="4" class="text-center text-muted py-4">All active products have more than 10 units.</td></tr><?php endif; foreach ($lowStock as $product): ?><tr><td class="fw-semibold"><?= htmlspecialchars($product['product_name']) ?></td><td><?= htmlspecialchars($product['size']) ?></td><td><span class="stock-pill low"><?= (int)$product['stock'] ?> left</span></td><td><a class="btn btn-sm btn-light" href="admin_stock.php">Restock</a></td></tr><?php endforeach; ?></tbody></table></div></div></section><section class="col-xl-5"><div class="admin-panel card-body h-100"><div class="section-head"><div><h2>Quick actions</h2><p>Common tasks for today.</p></div></div><div class="quick-links"><a class="quick-link" href="admin_products.php"><i class="fa-solid fa-circle-plus"></i>Add a product</a><a class="quick-link" href="admin_stock.php"><i class="fa-solid fa-arrow-right-arrow-left"></i>Update stock</a><a class="quick-link" href="admin_payments.php"><i class="fa-solid fa-circle-check"></i>Confirm payment</a></div><hr class="my-4"><h2 class="h6 fw-bold" style="color:#0f1c5c">Recent stock activity</h2><?php foreach ($recent as $row): ?><div class="d-flex justify-content-between align-items-center border-bottom py-2"><div><strong class="d-block small"><?= htmlspecialchars($row['product_name']) ?></strong><span class="text-muted" style="font-size:11px"><?= htmlspecialchars($row['transaction_type']) ?> · <?= htmlspecialchars($row['transaction_date']) ?></span></div><span class="fw-bold small"><?= (int)$row['quantity'] ?></span></div><?php endforeach; ?></div></section></div></main></body></html>
